INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(22501, 'Matthew 14:19', 'Matthew', 14, 19, '&nbsp;بيا هغۀ خلقو ته حکم ورکړو چې په کبل پېنډه جوړه کړئ. بيا هغۀ دا پينځۀ روټۍ او دوه کبان واخستل، آسمان ته يې پاس وکتل، برکت يې ورکړو او روټۍ يې ماتې کړې او هغه يې مريدانو له ورکړې او مريدانو هغه په خلقو تقسيم کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22502, 'Matthew 14:20', 'Matthew', 14, 20, '&nbsp;هغوئ ټولو ښۀ په مړه ګېډه خوراک وکړو او هغوئ چې پاتې شوې ټوکړې راټولې کړې نو دولس ټوکرۍ ترې ډکې شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22503, 'Matthew 14:21', 'Matthew', 14, 21, '&nbsp;نو خوا او شا پينځۀ زره سړو دغه روټۍ خوړلې وه چې ښځې او ماشومان په کښې شمار نۀ وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22504, 'Matthew 14:22', 'Matthew', 14, 22, '&nbsp;بيا سمدستى عيسىٰ خپل مريدان کِشتۍ ته وخېژول چې د هغوئ نه وړاندې د درياب پورې غاړې ته لاړ شى او د خلقو ګڼه يې خوره کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22505, 'Matthew 14:23', 'Matthew', 14, 23, '&nbsp;او چې خلق يې رُخصت کړل نو په خپله غرۀ ته لاړو چې يواځې دُعا وکړى او کله چې ماښام ناوخته شو، هغه هلته يواځې وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22506, 'Matthew 14:24', 'Matthew', 14, 24, '&nbsp;په هم هغه وخت کښې مريدانو ته د وچې نه ډېر وړاندې په اوبو کښې تکليف جوړ شو ځکه چې کشتۍ د سختو چپو او د مخالف هوا په وجه په درياب کښې په چورليدو وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22507, 'Matthew 14:25', 'Matthew', 14, 25, '&nbsp;عيسىٰ په شپه کښې د سحر کېدو نه لږ وړاندې د اوبو دپاسه روان وو او د مريدانو خوا ته راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22508, 'Matthew 14:26', 'Matthew', 14, 26, '&nbsp;هر کله چې مريدانو هغه د اوبو دپاسه روان وليدو نو هغوئ ويرېدل، او چغې يې کړې، ”دا خو پيرے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22509, 'Matthew 14:27', 'Matthew', 14, 27, '&nbsp;عيسىٰ ورته سمدستى وفرمائيل چې، ”مۀ يرېږئ. دا زۀ يم چې يره ونۀ کړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22510, 'Matthew 14:28', 'Matthew', 14, 28, '&nbsp;پطروس عيسىٰ ته ووئيل چې، ”مالِکه، کۀ چرې دا تۀ يې نو ما ته حُکم راکړه چې زۀ هم د اوبو دپاسه درشم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22511, 'Matthew 14:29', 'Matthew', 14, 29, '&nbsp;عيسىٰ ورته وفرمائيل چې، ”راځه.“ بيا پطروس د کِشتۍ نه کوز شو او د اوبو دپاسه د عيسىٰ خوا ته ورروان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22512, 'Matthew 14:30', 'Matthew', 14, 30, '&nbsp;خو هر کله چې هغۀ د طوفان زور وليدلو نو هغه وويرېدو، او چې ډوبېدو نو چغې يې کړې چې، ”مالِکه، ما بچ کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22513, 'Matthew 14:31', 'Matthew', 14, 31, '&nbsp;عيسىٰ سمدستى خپل لاس وراوږد کړو او هغه يې د لاسه ونيوو او ورته يې وفرمائيل، ”ستا عقيده څومره کمزورې ده. شک دې ولې وکړو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22514, 'Matthew 14:32', 'Matthew', 14, 32, '&nbsp;هغوئ چې کله په کِشتۍ کښې سوارۀ شول بيا طوفان ودرېدلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22515, 'Matthew 14:33', 'Matthew', 14, 33, '&nbsp;نو په کشتۍ کښې ناست مريدان ورته په سجده شول او وې وئيل، ”بې‌شکه، چې تۀ د خُدائ پاک زوئ يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22516, 'Matthew 14:34', 'Matthew', 14, 34, '&nbsp;کله چې هغوئ پورې غاړې ته ورسېدل نو هغوئ د ګِنيسرت علاقې ته راغلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22517, 'Matthew 14:35', 'Matthew', 14, 35, '&nbsp;د هغه ځائ خلقو عيسىٰ وپېژندو او ګېرچاپېره خلق يې خبر کړل او ټول بيماران يې ورله راوستل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22518, 'Matthew 14:36', 'Matthew', 14, 36, '&nbsp;او هغۀ ته يې مِنت وکړو چې دوئ ته دومره اجازت ورکړه چې ستا لمنې له لاس وروړى، او هر چا چې لاس وروړو، هغوئ بلکل روغ رمټ شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22519, 'Matthew 15:1', 'Matthew', 15, 1, '&nbsp;بيا د فريسيانو او د شرعې د عالمانو يوه ډله د يروشلم نه عيسىٰ له راغله او دا تپوس يې ترې وکړو چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22520, 'Matthew 15:2', 'Matthew', 15, 2, '&nbsp;”ستا مريدان ولې پخوانى رسمونه ماتوى او دوئ له چې څنګه د روټۍ نه وړاندې لاسونه وينځل په کار دى، نۀ وينځى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22521, 'Matthew 15:3', 'Matthew', 15, 3, '&nbsp;هغۀ ورته په جواب کښې وفرمائيل چې، ”دا تاسو څۀ کوئ چې د خپلو رواياتو د خاطره د خُدائ پاک حکم ماتوئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22522, 'Matthew 15:4', 'Matthew', 15, 4, '&nbsp;ځکه چې خُدائ پاک فرمائيلى دى چې د خپل مور او پلار عزت کوئ، او هر څوک چې خپل مور يا پلار ته بدرد وائى هغه دې قتل کړے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22523, 'Matthew 15:5', 'Matthew', 15, 5, '&nbsp;خو تاسو خلقو ته دا تعليم ورکوئ چې دا ټيک خبره ده چې کۀ څوک خپل مور او پلار ته دا ووائى چې، ”ستا چې څۀ په کار وُو هغه ما د خُدائ پاک په نامه ورکړل، مطلب دا چې ما د خُدائ پاک په نامه ورکړل،“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22524, 'Matthew 15:6', 'Matthew', 15, 6, '&nbsp;نو هغه نور د مور او پلار د حق نه مجبور نۀ دے. نو دغه شان تاسو د خپلو رواياتو په وجه د خُدائ پاک حُکمونه منسوخ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22525, 'Matthew 15:7', 'Matthew', 15, 7, '&nbsp;اے مُنافقانو، يشعياه نبى ستاسو په حقله په رښتيا سره دا پېشګوئې کړې وه، کله چې هغۀ وفرمائيل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22526, 'Matthew 15:8', 'Matthew', 15, 8, '&nbsp;دا خلق تش په خولۀ زما عزت کوى خو زړونه يې رانه ډېر لرې دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22527, 'Matthew 15:9', 'Matthew', 15, 9, '&nbsp;دوئ بې‌فائدې زما عبادت کوى، ځکه چې دوئ خلقو ته د انسانانو حُکمونه د تعليم په ډول ورکوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22528, 'Matthew 15:10', 'Matthew', 15, 10, '&nbsp;بيا هغۀ خلقو ته آواز وکړو او وې فرمائيل چې، ”زما خبره واورئ او ځان پرې پوهه کړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22529, 'Matthew 15:11', 'Matthew', 15, 11, '&nbsp;څۀ چې په خولۀ دننه کيږى په هغې يو کس نۀ پليتيږى، خو په هره هغه خبره پليتيږى څۀ چې د هغۀ د خولې نه راوځى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22530, 'Matthew 15:12', 'Matthew', 15, 12, '&nbsp;بيا مريدان عيسىٰ له راغلل او وې وئيل چې، ”تۀ خبر يې چې فريسيانو ستا دا خبرې بدې ګڼلى دى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22531, 'Matthew 15:13', 'Matthew', 15, 13, '&nbsp;هغۀ جواب ورکړو چې، ”هر يو بوټے چې زما آسمانى پلار لګولے نۀ وى هغه به د بېخه وويستلے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22532, 'Matthew 15:14', 'Matthew', 15, 14, '&nbsp;د دوئ پرواه مۀ کوئ. دا ړاندۀ لارښودونکى دى، نو کۀ چرې يو ړوند بل ړوند ته لارښودنه کوى نو دواړه به په کنده کښې وغورزيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22533, 'Matthew 15:15', 'Matthew', 15, 15, '&nbsp;بيا پطروس ووئيل چې، ”مونږ ته دا مِثال تشريح کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22534, 'Matthew 15:16', 'Matthew', 15, 16, '&nbsp;عيسىٰ جواب ورکړو، ”ولې تاسو هم لا تر اوسه د نورو په شان ناپوهه يئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22535, 'Matthew 15:17', 'Matthew', 15, 17, '&nbsp;ولې تاسو دا نۀ وينئ چې کوم څيز چې په خولۀ دننه شى، خېټې ته لاړ شى او بيا هغه د بدن نه بهر وځى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22536, 'Matthew 15:18', 'Matthew', 15, 18, '&nbsp;خو چې څۀ په خولې وئيلے شى هغه د زړۀ نه راوځى او دغه خبرې دى چې انسان پليتوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22537, 'Matthew 15:19', 'Matthew', 15, 19, '&nbsp;ځکه چې ټول وران خيالونه، لکه قتل، زنا، حرامکارى، غلا، د دروغو ګواهى او غېبت د زړۀ نه راوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22538, 'Matthew 15:20', 'Matthew', 15, 20, '&nbsp;او دا هغه کارونه دى چې انسان پليتوى، خو په ناوينځلو لاسونو باندې په خوراک کولو، انسان نۀ پليتيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22539, 'Matthew 15:21', 'Matthew', 15, 21, '&nbsp;بيا عيسىٰ هغه ځائ پرېښودو او د صور او د صيدا علاقې ته راغلو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22540, 'Matthew 15:22', 'Matthew', 15, 22, '&nbsp;او د هغې علاقې يوه کنعانى ښځه بهر راووتله او په چغه يې ووئيل، ”اے مالِکه، په ما رحم وکړه. اے د داؤد زويه، زما لور پيريانو سخته نيولې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22541, 'Matthew 15:23', 'Matthew', 15, 23, '&nbsp;خو هغۀ هيڅ جواب ورنۀ کړو. د هغۀ مريدان راغلل او زارى يې وکړه چې، ”دا ښځه لرې کړه ځکه چې په مونږ پسې بې‌واره چغې وهى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22542, 'Matthew 15:24', 'Matthew', 15, 24, '&nbsp;عيسىٰ جواب ورکړو ”زۀ صرف د بنى اِسرائيل د خاندان د ورکو شوو ګډو دپاره رالېږلے شوے يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22543, 'Matthew 15:25', 'Matthew', 15, 25, '&nbsp;خو هغه ښځه راغله، د دۀ په پښو پرېوته او چغې يې کړې، ”مالِکه، زما مدد وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22544, 'Matthew 15:26', 'Matthew', 15, 26, '&nbsp;عيسىٰ په جواب کښې وفرمائيل، ”دا مناسب نۀ دى چې د ماشومانو برخه روټۍ دې څوک واخلى او سپو ته دې واچوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22545, 'Matthew 15:27', 'Matthew', 15, 27, '&nbsp;هغې جواب ورکړو چې، ”آو مالِکه، خو بيا سپى هم هغه ټوکړې خورى کومې چې د مالِکانو د دسترخوان نه وغورزيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22546, 'Matthew 15:28', 'Matthew', 15, 28, '&nbsp;نو بيا عيسىٰ جواب ورکړو چې، ”تۀ څومره د لوئ ايمان لرونکې ښځه يې، نو څنګه چې تۀ غواړې، هغه شان دې وشى.“ او هم په هغه ساعت د هغې لور جوړه شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22547, 'Matthew 15:29', 'Matthew', 15, 29, '&nbsp;کله چې عيسىٰ د دغه ځايه د ګليل درياب په غاړه روان شو نو هغه بيا غرۀ ته بره لاړو او هلته کښېناستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22548, 'Matthew 15:30', 'Matthew', 15, 30, '&nbsp;نو ډېر خلق ورله راغلل چې ورسره ګوډيان، ړاندۀ، شليان، ګونګيان، او نور ډېر بيماران وُو. او هغوئ هغه خلق د عيسىٰ پښو ته څملول او هغۀ هغوئ روغ کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22549, 'Matthew 15:31', 'Matthew', 15, 31, '&nbsp;هغه خلق په دې ډېر حېران شول چې چاړاګانو خبرې وکړلې، مات ګوډ خلق روغ شول او ګرځېدل او ړاندۀ بينا شول او ټولو په دې د بنى اِسرائيلو د خُدائ پاک لوئى بيان کړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22550, 'Matthew 15:32', 'Matthew', 15, 32, '&nbsp;عيسىٰ خپل مريدان راوبلل او ورته يې وفرمائيل چې، ”په دې خلقو زما زړۀ سوزى، دوئ د درېو ورځو راسې زما سره دى او د خوراک دپاره ورسره هيڅ نشته. زۀ دوئ اوږى رخصتول نۀ غواړم، هسې نه چې په لاره کښې بې‌هوشه شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22551, 'Matthew 15:33', 'Matthew', 15, 33, '&nbsp;مريدانو جواب ورکړو چې، ”په دې خوشى بيابان کښې به دومره خلقو له مونږ روټۍ د کومه راوړو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22552, 'Matthew 15:34', 'Matthew', 15, 34, '&nbsp;عيسىٰ ورته وفرمائيل چې، ”تاسو سره څو روټۍ دى؟“ هغوئ جواب ورکړو چې، ”اووۀ روټۍ او يو څو واړۀ کبان.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22553, 'Matthew 15:35', 'Matthew', 15, 35, '&nbsp;نو عيسىٰ خلقو ته وفرمائيل چې په زمکه کښېنئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22554, 'Matthew 15:36', 'Matthew', 15, 36, '&nbsp;نو هغه اووۀ روټۍ او کبان يې راواخستل، او د خُدائ پاک شُکر يې پرې وويستو، روټۍ او کبان يې ټوکړې کړل او مريدانو له يې ورکړل، او مريدانو په خلقو وويشل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22555, 'Matthew 15:37', 'Matthew', 15, 37, '&nbsp;ټولو ځانونه ښۀ ماړۀ کړل. او چې څۀ ټوکړې ترې پاتې شوې نو هغه يې راټولې کړلې. هغه دومره وې چې اووۀ غټې ټوکرۍ ترې ډکې شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22556, 'Matthew 15:38', 'Matthew', 15, 38, '&nbsp;د بچو او ښځو نه علاوه څلورو زرو کسانو هغه روټۍ وخوړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22557, 'Matthew 15:39', 'Matthew', 15, 39, '&nbsp;هغۀ بيا خلق رُخصت کړل، کِشتۍ ته وختلو او د مګدن علاقې ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22558, 'Matthew 16:1', 'Matthew', 16, 1, '&nbsp;فريسيان او صدوقيان عيسىٰ له راغلل او د آزمېښت په توګه يې ورته وفرمائيل چې، ”مونږ ته يوه آسمانى معجزه وښايه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22559, 'Matthew 16:2', 'Matthew', 16, 2, '&nbsp;هغۀ جواب ورکړو چې، ”تاسو په ماښام کښې وايئ چې موسم به ښۀ شى ځکه چې آسمان سور دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22560, 'Matthew 16:3', 'Matthew', 16, 3, '&nbsp;او د سحر په وخت وايئ چې نن به سيلۍ راشى ځکه چې آسمان سور او دوند دے. تاسو د آسمان د مخ تعبير کولے شئ خو د زمانو په نښو نۀ پوهېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22561, 'Matthew 16:4', 'Matthew', 16, 4, '&nbsp;دا يوه بدکاره او زناکاره پيړۍ ده چې نښې غواړى خو د يُونس نبى د نښې نه سېوا يوه نښه به هم دوئ ته ورنۀ کړے شى.“ نو بيا هغه ترې روان شو او هغوئ يې پرېښودل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22562, 'Matthew 16:5', 'Matthew', 16, 5, '&nbsp;خو کله چې هغوئ بلې غاړې ته واوړېدل نو بيا مريدانو ته دا پته ولګېده چې روټۍ ورنه د ياده وتلې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22563, 'Matthew 16:6', 'Matthew', 16, 6, '&nbsp;عيسىٰ هغوئ ته وفرمائيل چې، ”د فريسيانو او د صدوقيانو د خمبيرې نه ځان ساتئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22564, 'Matthew 16:7', 'Matthew', 16, 7, '&nbsp;هغوئ په خپلو کښې يو بل ته ووئيل چې، ”دا ځکه چې مونږ روټۍ نۀ ده راوړې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22565, 'Matthew 16:8', 'Matthew', 16, 8, '&nbsp;عيسىٰ په دې خبر شو چې هغوئ د څۀ په حقله خبرې کوى، نو د هغوئ نه يې تپوس وکړو، ”اے بې‌ايمانه خلقو، دا تاسو داسې خبرې ولې کوئ چې ګنې روټۍ درسره نشته؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22566, 'Matthew 16:9', 'Matthew', 16, 9, '&nbsp;تاسو لا تر اوسه نۀ پوهېږئ؟ ولې تاسو ته هغه پينځۀ روټۍ د پينځۀ زره کسانو دپاره يادې نۀ دى، او تاسو څومره ټوکرۍ ترې اوچتې کړې وې؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22567, 'Matthew 16:10', 'Matthew', 16, 10, '&nbsp;بيا هغه اووۀ روټۍ د څلورو زرو کسانو دپاره، او څومره غټې ټوکرۍ تاسو ته پاتې شوې وې؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22568, 'Matthew 16:11', 'Matthew', 16, 11, '&nbsp;تاسو څنګه په دې خبره پوهه نۀ شوئ چې ما خو د روټۍ ذکر نۀ کولو؟ ما درته فرمائيلى وُو چې د فريسيانو او صدوقيانو د خمبيرې نه به ځان ساتئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22569, 'Matthew 16:12', 'Matthew', 16, 12, '&nbsp;بيا هغوئ په دې مطلب پوهه شول چې د روټۍ او د خمبيرې نه ځان ساتل نۀ دى، خو د فريسيانو او صدوقيانو د تعليم نه ځان ساتل دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22570, 'Matthew 16:13', 'Matthew', 16, 13, '&nbsp;خو کله چې هغوئ د قيصريه فيليپى علاقې ته راغلل نو عيسىٰ د خپلو مريدانو نه تپوس وکړو چې، ”خلق څۀ وائى چې اِبن آدم څوک دے؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22571, 'Matthew 16:14', 'Matthew', 16, 14, '&nbsp;هغوئ جواب ورکړو، ”ځينې وائى چې بپتسمه ورکوونکے يحيىٰ دے، څۀ دې الياس ګڼى، او څۀ نور دې اوس هم يرمياه يا د نبيانو نه يو ګڼى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22572, 'Matthew 16:15', 'Matthew', 16, 15, '&nbsp;هغۀ ورته وفرمائيل چې، ”تاسو څۀ وايئ، چې زۀ څوک يم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22573, 'Matthew 16:16', 'Matthew', 16, 16, '&nbsp;شمعون پطروس جواب ورکړو، ”تۀ مسيح د ژوندى خُدائ پاک زوئ يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22574, 'Matthew 16:17', 'Matthew', 16, 17, '&nbsp;بيا عيسىٰ وفرمائيل، ”اے د يوحنا زويه شمعونه، تۀ بې‌شکه بختور يې. تا دا خبره د فانى انسان نه نۀ ده زده کړې بلکې زما آسمانى پلار دا ستا په زړۀ کښې اچولې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22575, 'Matthew 16:18', 'Matthew', 16, 18, '&nbsp;خو زۀ تا ته دا وايم چې تۀ پطروس يې، چې معنىٰ يې ګټ دے، چې زۀ به خپل جماعت په دې ګټ آبادوم، او په دې به مرګ هم هيڅکله غالبېدے نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22576, 'Matthew 16:19', 'Matthew', 16, 19, '&nbsp;زۀ به تا له د آسمان د بادشاهۍ چابيانې درکړم، تۀ چې په زمکه څۀ منع کړې هغه به په آسمان کښې هم منع شى، او څۀ چې تۀ په زمکه روا کړې هغه به په آسمان کښې هم روا شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22577, 'Matthew 16:20', 'Matthew', 16, 20, '&nbsp;بيا هغۀ مريدان په سختۍ سره منع کړل چې، ”هيچا ته مۀ وايئ چې هغه مسيح دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22578, 'Matthew 16:21', 'Matthew', 16, 21, '&nbsp;د هغه وخت نه عيسىٰ خپلو مريدانو ته دا خبره څرګنده کړه چې، ”هغه به ضرور يروشلم ته لاړ شى او د مشرانو او د مشرانو اِمامانو او د شرعې د عالمانو د لاسه به ډيرې سختۍ وزغمى، او هغه به ووژلے شى او په درېمه ورځ به بيا راژوندے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22579, 'Matthew 16:22', 'Matthew', 16, 22, '&nbsp;بيا پطروس هغه د لاس نه ونيوو او يوې خوا ته يې ورته ووئيل چې، ”خُدائ دې نۀ کړى مالِکه، په تا دې داسې هيڅکله هم ونۀ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22580, 'Matthew 16:23', 'Matthew', 16, 23, '&nbsp;بيا عيسىٰ مخ ورواړولو او پطروس ته يې وفرمائيل، ”رانه لرې شه شېطانه، تۀ زما د لارې خنډ يې، تۀ د بنى آدمو په شان سوچ کوې، نه چې د خُدائ پاک په شان.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22581, 'Matthew 16:24', 'Matthew', 16, 24, '&nbsp;بيا عيسىٰ خپلو مريدانو ته وفرمائيل چې، ”کۀ څوک زما مريد جوړېدل غواړى، هغه دې د خپل ځان نه منکر شى، خپله سولۍ دې راواخلى او ما پسې دې راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22582, 'Matthew 16:25', 'Matthew', 16, 25, '&nbsp;څوک چې خپل ځان ساتل غواړى هغه به يې بائيلى، خو څوک چې زما د خاطره خپل ژوند بائيلى، هغه به يې حاصل کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22583, 'Matthew 16:26', 'Matthew', 16, 26, '&nbsp;کۀ څوک د خپل ابدى ژوند په بدله کښې ټوله دُنيا ومومى نو هغۀ ځان ته څۀ فائده ورکړه؟ او د خپل ژوند په بدله کښې هغه څۀ ورکولے شى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22584, 'Matthew 16:27', 'Matthew', 16, 27, '&nbsp;ځکه چې اِبن آدم به د خپل پلار په لويئ کښې د خپلو فرښتو سره راځى او بيا به هغه هر چا ته د خپل عمل بدله ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22585, 'Matthew 16:28', 'Matthew', 16, 28, '&nbsp;زۀ تاسو ته رښتيا وايم چې دلته ځينې داسې کسان ولاړ دى چې تر هغې به نۀ مرى ترڅو چې هغوئ اِبن آدم خپلې بادشاهۍ ته په راتلو ونۀ وينى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22586, 'Matthew 17:1', 'Matthew', 17, 1, '&nbsp;شپږ ورځې پس عيسىٰ د ځان سره پطروس يعقوب او د هغۀ ورور يوحنا يو اوچت غرۀ ته وخېژول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22587, 'Matthew 17:2', 'Matthew', 17, 2, '&nbsp;او د هغوئ په وړاندې د هغۀ شکل بدل کړے شو او د هغۀ مخ لکه د نمر وځلېدو او د هغۀ جامې لکه د رڼا سپينې شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22588, 'Matthew 17:3', 'Matthew', 17, 3, '&nbsp;نو ناګهانه هغوئ ته موسىٰ او الياس ښکاره شُو چې د هغۀ سره يې خبرې کولې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22589, 'Matthew 17:4', 'Matthew', 17, 4, '&nbsp;نو پطروس عيسىٰ ته ووئيل چې، ”مالِکه، زمونږ دپاره دلته پاتې کېدل ښۀ دى. کۀ تۀ غواړې نو زۀ به دلته درې جونګړې، يوه ستا دپاره، يوه موسىٰ دپاره او يوه الياس دپاره جوړه کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22590, 'Matthew 17:5', 'Matthew', 17, 5, '&nbsp;هغۀ لا دا خبرې کولې چې ناګهانه يوه پړقېدونکې وريځ راخوره شوه او په هغوئ يې سورے وکړو او د وريځې نه آواز وفرمائيل، ”دا زما محبوب زوئ دے د چا نه چې زۀ راضى يم. د هغۀ خبرې واورئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22591, 'Matthew 17:6', 'Matthew', 17, 6, '&nbsp;د دې آواز په اورېدو مريدان د يرې نه پړمخې پرېوتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22592, 'Matthew 17:7', 'Matthew', 17, 7, '&nbsp;خو بيا عيسىٰ هغوئ له ورغلو، په هغوئ يې لاس ولګولو او ورته يې وفرمائيل، ”پاڅئ، مۀ يرېږئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22593, 'Matthew 17:8', 'Matthew', 17, 8, '&nbsp;او کله چې هغوئ بره نظر واچولو نو څوک يې هم ونۀ ليدل خو صرف عيسىٰ د هغوئ سره ولاړ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22594, 'Matthew 17:9', 'Matthew', 17, 9, '&nbsp;نو کله چې هغوئ د غرۀ نه راکوزېدل نو عيسىٰ هغوئ ته حکم ورکړو چې، ”د دې رويا په حقله تر هغې چا ته څۀ مۀ وايئ ترڅو چې اِبن آدم د مړو نه بيا ژوندے پورته کړے شوے نۀ وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22595, 'Matthew 17:10', 'Matthew', 17, 10, '&nbsp;نو مريدانو د هغۀ نه تپوس وکړو چې، ”بيا زمونږ د شرعې عالمان داسې ولې وائى چې الياس به ضرور وړومبے راځى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22596, 'Matthew 17:11', 'Matthew', 17, 11, '&nbsp;هغۀ ورته وفرمائيل چې، ”آو، الياس به راځى او هر څۀ به سموى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22597, 'Matthew 17:12', 'Matthew', 17, 12, '&nbsp;خو زۀ تاسو ته وايم چې الياس خو راغلے دے، خو هغوئ نۀ دے پېژندلے او څۀ چې دوئ غوښتل ورسره يې وکړل. او دغه شان به اِبن آدم هم د هغوئ د لاسه ودرديږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22598, 'Matthew 17:13', 'Matthew', 17, 13, '&nbsp;بيا مريدان پوهه شول چې هغه د بپتسمه ورکوونکى يحيىٰ په باب کښې فرمائى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22599, 'Matthew 17:14', 'Matthew', 17, 14, '&nbsp;کله چې هغوئ خلقو ته واپس راغلل نو يو سړے عيسىٰ له راغلو، د هغۀ په وړاندې په ګوډو شو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(22600, 'Matthew 17:15', 'Matthew', 17, 15, '&nbsp;او وې وئيل، ”مالِکه، زما په زوئ رحم وکړه. په هغۀ مِرګى راځى او ډېر يې زوروى کله يې په اور او کله يې په اوبو کښې غورزوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');